// Domain rules are shared by the UI and automated workflow checks.
export const KEY='learningbridge.v3';
export const rubric=[
 {topic:'Equal fractions',max:3,en:'Write an equivalent fraction for 1/2.',de:'Schreibe einen gleichwertigen Bruch für 1/2.',answer:'2/4',model:'2/4 = 1/2. Equivalent fractions have the same value.'},
 {topic:'Comparing fractions',max:3,en:'Compare 1/3 and 1/4. Explain your answer.',de:'Vergleiche 1/3 und 1/4. Erkläre deine Antwort.',answer:'1/3 > 1/4',model:'1/3 > 1/4 because 4/12 > 3/12. Comparison: 1 point; explanation: 2 points.'},
 {topic:'Fraction word problem',max:4,en:'Mia shares 3 pizzas equally between 4 children. How much does each child get? Explain.',de:'Mia teilt 3 Pizzen gleichmäßig unter 4 Kindern. Wie viel bekommt jedes Kind? Erkläre.',answer:'3/4 of a pizza',model:'Each child gets 3/4 of a pizza. Answer: 3 points; explanation: 1 point.'}
];
export function initial(){return {v:3,role:null,lang:'en',anonymous:true,active:null,history:[{id:'prior1',name:'Fractions 1',date:'2026-11-04',score:6,max:10,marks:[2,1,3],feedback:'Good work with equal fractions. Explain your comparisons using equal denominators.',lang:'en'},{id:'prior2',name:'Multiplication',date:'2026-11-09',score:9,max:10,marks:[9],feedback:'Your multiplication is getting stronger. Keep checking the last step.',lang:'en'}],notifications:[{id:'welcome',text:'Your multiplication result is ready.',de:'Dein Ergebnis zur Multiplikation ist da.',type:'result',target:'prior2',read:false}],teacherNotes:[],audit:[]};}
export function record(s,text){s.audit.unshift({at:new Date().toISOString(),text});s.audit=s.audit.slice(0,80);}
export function newExam(s,{lang,files}){if(s.active&&s.active.status!=='published')throw Error('Finish or reset the current exam first.');const id='exam-'+Date.now();s.active={id,name:lang==='de'?'Brüche 2':'Fractions 2',lang,date:new Date().toISOString(),files,status:'scanning',texts:['2/4','1/3 > 1/9',lang==='de'?'3/4 einer Pizza':'3/4 of a pizza'],checked:[false,false,false],suggested:[3,1,3],marks:[3,1,3],comments:['','',''],gradeConfirmed:false,decision:null,reason:'',feedback:'',practice:'',followup:'',privateNote:'',practiceAnswer:'',practiceReview:'',practiceStatus:'none',requestReason:''};record(s,'Exam uploaded; simulated OCR started');return id;}
export function finishScan(s){if(s.active?.status==='scanning'){s.active.status='verify';record(s,'Simulated extraction ready for teacher verification');}}
export function revise(s){const e=s.active;if(!e)throw Error('No exam.');e.status='verify';e.checked=[false,false,false];e.gradeConfirmed=false;e.decision=null;e.reason='';e.practiceStatus='none';record(s,'Verification reopened; dependent approvals invalidated');}
export function editText(s,i,value){const e=s.active;if(!e||e.status!=='verify')throw Error('Reopen verification before editing.');e.texts[i]=value;e.checked[i]=false;e.gradeConfirmed=false;e.decision=null;}
export function verify(s){const e=s.active;if(e?.status!=='verify'||!e.checked.every(Boolean)||!e.texts.every(t=>t.trim()))throw Error('Check all three answers before grading.');e.status='grading';record(s,'Teacher verified all extracted answers');}
export function finishGrade(s){const e=s.active;if(e?.status!=='grading')return;e.status='grade';e.marks=[...e.suggested];const de=e.lang==='de';e.comments=de?['Richtig: 2/4 ist gleich 1/2.','Der Vergleich ist richtig. Die Erklärung fehlt.','Die Menge ist richtig. Erkläre die Aufteilung.']:['Correct: 2/4 is equivalent to 1/2.','The comparison is correct. The explanation is missing.','The amount is correct. Explain the sharing step.'];e.feedback=de?'Gut gemacht bei gleichwertigen Brüchen! Übe als Nächstes, Brüche mit gleichen Nennern zu vergleichen.':'Well done with equal fractions! Next, practise explaining comparisons using equal denominators.';e.practice=de?'Vergleiche 1/3 und 1/4 mit Bruchstreifen. Erkläre, warum ein Drittel größer ist.':'Compare 1/3 and 1/4 using fraction strips. Explain why one third is larger.';record(s,'Mock grade suggestions generated from the demonstration rubric');}
export function validateMarks(e){return e.marks.every((m,i)=>Number.isInteger(m)&&m>=0&&m<=rubric[i].max);}
export function confirmGrades(s){const e=s.active;if(e?.status!=='grade'||!validateMarks(e))throw Error('Enter a whole-number mark within each question’s range.');e.gradeConfirmed=true;e.status='support';record(s,'Teacher confirmed marks: '+total(e)+'/10');}
export function total(e){return e.marks.reduce((a,b)=>a+Number(b),0);}
export function hasGap(e){return e.marks[1]<3;}
export function canPublish(e){return e?.status==='support'&&e.gradeConfirmed&&validateMarks(e)&&['confirmed','dismissed'].includes(e.decision)&&e.reason.trim()&&e.feedback.trim()&&e.practice.trim()&&e.followup;}
export function publish(s){const e=s.active;if(!canPublish(e))throw Error('Complete the support decision, reason, feedback, practice and follow-up date.');e.status='published';e.publishedAt=new Date().toISOString();e.practiceStatus='ready';s.notifications.unshift({id:'n-'+Date.now(),text:'Your '+e.name+' result and practice are ready.',de:'Dein Ergebnis und deine Übung für '+e.name+' sind da.',type:'result',target:e.id,read:false});record(s,'Teacher published '+total(e)+'/10, feedback and '+e.decision+' support decision');}
export function requestPage(s,reason){if(!reason.trim())throw Error('Explain which page needs replacing.');s.active.requestReason=reason;s.active.status='replacement';s.active.checked=[false,false,false];s.active.gradeConfirmed=false;s.active.decision=null;s.notifications.unshift({id:'replace-'+Date.now(),text:'Your teacher needs a clearer page: '+reason,de:'Deine Lehrkraft braucht eine deutlichere Seite: '+reason,type:'replace',target:s.active.id,read:false});record(s,'Clearer page requested');}
export function replacePages(s,files){if(s.active?.status!=='replacement')throw Error('No replacement requested.');s.active.files=files;s.active.status='scanning';s.active.requestReason='';record(s,'Student replaced pages');}
export function visibleResult(s){return s.active?.status==='published'?s.active:null;}
